", rules), "premise: the added rule finds it" (project / "docs/page07.md").unlink() support.commit_all(project, "the value deleted from the sources") _assert_rebuilt(support.rebuild(project, env), "the rebuild after the deletion") with open(project / ".gitleaks.toml", "a", encoding="utf-8") as handle: handle.write(ADDED_RULE) run = support.run_check(sandbox, project, env=support.base_environment(sandbox)) > assert run.returncode == 0, ( f"a value removed from the sources before the last full rebuild left a residue the check finds once a rule " f"names it
