@pytest.mark.skipif(support.CODE_TOOL is None, reason="codebase-memory-mcp is not on PATH: no code-graph store") @needs_vectors def test_the_code_graph_store_holds_no_deleted_word_and_no_free_page_after_a_rebuild(sandbox, embedder): """Runs the code-graph tool's daemon: one of the cases that run alone (README).""" project = support.make_rebuild_project(sandbox, _files()) env = support.rebuild_environment(sandbox, embedder, with_code_tool=True) daemon = support.code_daemon_dir(project) try: _assert_rebuilt(support.rebuild(project, env), "the first rebuild", code=True) graph = project / R / "codeintel" code_stores = [path for path in support.sqlite_files(graph)] assert code_stores, "premise: the code-graph tool wrote a SQLite store under .gov-runtime/codeintel/" forms = support.word_forms(WORD) assert support.files_holding(graph, forms), "premise: the word reached the code-graph store" (project / "docs/page07.md").unlink() support.write(project / "src/app.py", "def keeper():\n return 2\n") for n in range(KEPT, PAGES): if n != 7: (project / f"docs/page{n:02d}.md").unlink() support.commit_all(project, "the word and most pages deleted") _assert_rebuilt(support.rebuild(project, env), "the rebuild after the deletion", code=True) stores = _sqlite_report(project) > assert all(count == 0 for count in stores.values()), ( f"after a full rebuild, SQLite stores hold free pages: { {r: n for r, n in stores.items() if n} }") E AssertionError: after a full rebuild, SQLite stores hold free pages: {'.gov-runtime/store.db': 219} E assert False E + where False = all(<generator object test_the_code_graph_store_holds_no_deleted_word_and_no_free_page_after_a_rebuild.<locals>.<genexpr> at 0x70eb10a68fb0>)
